class Solution {
    public boolean isPalindrome(String s) {
        String clean = s.replaceAll("[^A-Za-z0-9]", "").toLowerCase();
        int i = 0, j = clean.length() - 1;
        while (i < j) {
            if (clean.charAt(i++) != clean.charAt(j--)) return false;
        }
        return true;
    }
}

import java.util.Arrays;
class Solution {
    public boolean containsDuplicate(int[] nums) {
        int[] copy = nums.clone();
        Arrays.sort(copy);
        for (int i = 1; i < copy.length; i++) if (copy[i] == copy[i - 1]) return true;
        return false;
    }
}

class Solution {
    public boolean isValid(String s) {
        int before;
        do {
            before = s.length();
            s = s.replace("()", "").replace("[]", "").replace("{}", "");
        } while (s.length() != before);
        return s.isEmpty();
    }
}

class Solution {
    public int search(int[] nums, int target) {
        return find(nums, target, 0, nums.length - 1);
    }
    private int find(int[] nums, int target, int low, int high) {
        if (low > high) return -1;
        int mid = low + (high - low) / 2;
        if (nums[mid] == target) return mid;
        return nums[mid] < target ? find(nums, target, mid + 1, high) : find(nums, target, low, mid - 1);
    }
}

import java.util.ArrayList;
import java.util.List;
class Solution {
    public int[] merge(int[] a, int[] b) {
        List<Integer> out = new ArrayList<>();
        int i = 0, j = 0;
        while (i < a.length || j < b.length) {
            if (j == b.length || (i < a.length && a[i] <= b[j])) out.add(a[i++]);
            else out.add(b[j++]);
        }
        return out.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution {
    private final int[] memo = new int[46];
    public int climbStairs(int n) {
        if (n <= 2) return n;
        if (memo[n] != 0) return memo[n];
        return memo[n] = climbStairs(n - 1) + climbStairs(n - 2);
    }
}

import java.util.HashMap;
import java.util.Map;
class Solution {
    public int firstUniqChar(String s) {
        Map<Character, Integer> counts = new HashMap<>();
        for (char c : s.toCharArray()) counts.merge(c, 1, Integer::sum);
        for (Map.Entry<Character, Integer> e : counts.entrySet()) {
            if (e.getValue() == 1) return s.indexOf(e.getKey());
        }
        return -1;
    }
}

class Solution {
    public int maxSubArray(int[] nums) {
        int best = Integer.MIN_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int sum = 0;
            for (int j = i; j < nums.length; j++) {
                sum += nums[j];
                best = Math.max(best, sum);
            }
        }
        return best;
    }
}

import java.util.HashSet;
import java.util.Set;
class Solution {
    public int lengthOfLongestSubstring(String s) {
        Set<Character> window = new HashSet<>();
        int left = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            while (window.contains(s.charAt(right))) window.remove(s.charAt(left++));
            window.add(s.charAt(right));
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

